#!/usr/bin/env node
// dev-guardian launcher - generated by dev-spec-driven (dev-spec init --guardian; regenerated by
// init --guardian, removed by init --guardian off — an edit is overwritten).
//
// The project check "guardian" (.specs/roadmap.json meta.checks) runs, from the project root:
//   node .specs/guardian.cjs scan --project . --fail-on high --format json
// This file finds the newest installed dev-guardian at each run and hands its CLI the arguments after its own name, so the check
// keeps working after an update of either plugin. Where it looks: DEV_GUARDIAN_CLI (the path of a cli/dev-guardian.mjs) first;
// else Claude Code's plugin cache (under CLAUDE_CONFIG_DIR, else ~/.claude):
//   plugins/cache/<marketplace>/dev-guardian/<version>/cli/dev-guardian.mjs — the newest <version> by its numeric parts.
// Nothing found, or a CLI that does not load: exit 3 — dev-guardian's own code for a usage or configuration error.
"use strict";
const fs = require("fs");
const path = require("path");

const isFile = (f) => { try { return fs.statSync(f).isFile(); } catch { return false; } };
const list = (dir) => { try { return fs.readdirSync(dir); } catch { return []; } };
const parts = (v) => String(v).split(".").map((x) => parseInt(x, 10) || 0);
function newer(a, b) {
  const x = parts(a), y = parts(b);
  for (let i = 0; i < Math.max(x.length, y.length); i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0);
  return false;
}

function findCli(env) {
  const own = String(env.DEV_GUARDIAN_CLI || "").trim();
  if (own) return isFile(own) ? { cli: own } : { error: "DEV_GUARDIAN_CLI names no file (" + own + ")" };
  const home = String(env.CLAUDE_CONFIG_DIR || "").trim() || path.join(require("os").homedir(), ".claude");
  // (the paths are the user's own config folder and the folder names under it — nothing a request could steer)
  // nosemgrep: javascript.lang.security.audit.path-traversal.path-join-resolve-traversal.path-join-resolve-traversal
  const cache = path.join(home, "plugins", "cache");
  let best = null;
  for (const market of list(cache)) {
    // nosemgrep: javascript.lang.security.audit.path-traversal.path-join-resolve-traversal.path-join-resolve-traversal
    const base = path.join(cache, market, "dev-guardian");
    for (const version of list(base)) {
      // nosemgrep: javascript.lang.security.audit.path-traversal.path-join-resolve-traversal.path-join-resolve-traversal
      const cli = path.join(base, version, "cli", "dev-guardian.mjs");
      if (isFile(cli) && (!best || newer(version, best.version))) best = { version, cli };
    }
  }
  return best ? { cli: best.cli } : { error: "no dev-guardian plugin in " + cache + " — install it, or set DEV_GUARDIAN_CLI to the path of its cli/dev-guardian.mjs" };
}

const found = findCli(process.env);
if (found.error) {
  console.error("dev-guardian not found: " + found.error);
  process.exitCode = 3;
} else {
  // dev-guardian runs as the entry point (it compares argv[1] with its own path) and reads its arguments from argv[2] on
  process.argv[1] = found.cli;
  import("node:url").then((u) => import(u.pathToFileURL(found.cli).href)).catch((e) => {
    console.error("dev-guardian could not be loaded from " + found.cli + ": " + (e && e.message ? e.message : e));
    process.exitCode = 3;
  });
}
